import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{O as t}from"./framer-DPWtvxwd.js";import{En as n,Rt as r,or as i,t as a,v as o}from"./icons-CARiYJLk.js";import{n as s,t as c}from"./ArticleLayout-ZdbV-m2w.js";var l,u,d=e((()=>{a(),l=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Convoyage professionnel : quelle assurance pour le véhicule que vous déplacez ?`,description:`Mandataires, négociants, transporteurs : assurez chaque véhicule convoyé (roulant) avec une assurance temporaire de 1 à 90 jours, sans contrat annuel inutile. Attestation en 5 minutes.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/assurance-temporaire-convoyage-professionnel`,datePublished:`2026-06-03`,dateModified:`2026-06-03`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Convoyage professionnel : quelle assurance ?`,item:`https://assutempo.fr/articles/assurance-temporaire-convoyage-professionnel`}]},{"@context":`https://schema.org`,"@type":`HowTo`,name:`Comment assurer un véhicule à convoyer en 4 étapes`,totalTime:`PT5M`,step:[{"@type":`HowToStep`,position:1,name:`Choisissez la durée du convoyage (1 à 90 j)`,text:`Sélectionnez le nombre de jours correspondant à la durée du déplacement.`},{"@type":`HowToStep`,position:2,name:`Renseignez le véhicule à convoyer`,text:`Indiquez les informations du véhicule (carte grise, preuve de propriété ou numéro de châssis).`},{"@type":`HowToStep`,position:3,name:`Payez en ligne`,text:`Paiement sécurisé par carte bancaire, sans engagement.`},{"@type":`HowToStep`,position:4,name:`Recevez l'attestation (5 min)`,text:`Votre Mémo Véhicule Assuré et votre carte internationale d'assurance automobile arrivent par email.`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Un véhicule convoyé sur la route doit-il être assuré ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, la RC est obligatoire dès qu'il roule sur ses propres roues, même pour un trajet unique.`}},{"@type":`Question`,name:`Faut-il un contrat annuel pour convoyer un véhicule ?`,acceptedAnswer:{"@type":`Answer`,text:`Non. L'assurance temporaire (1 à 90 jours) couvre exactement la durée du convoyage, sans engagement.`}},{"@type":`Question`,name:`Assurance temporaire ou RC Pro convoyeur ?`,acceptedAnswer:{"@type":`Answer`,text:`Les deux sont distinctes et complémentaires : l'assurance temporaire couvre le véhicule pour rouler, la RC Pro couvre votre responsabilité professionnelle de convoyeur.`}},{"@type":`Question`,name:`Peut-on assurer un véhicule pas encore à mon nom ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, à partir de la carte grise, de la preuve de propriété ou du numéro de châssis.`}},{"@type":`Question`,name:`Le convoyage à l'étranger est-il couvert ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, la carte internationale d'assurance couvre les 34 pays.`}},{"@type":`Question`,name:`Reçoit-on une carte verte ?`,acceptedAnswer:{"@type":`Answer`,text:`Non, elle a été supprimée en avril 2024. Vous recevez un Mémo Véhicule Assuré et une carte internationale d'assurance automobile (valable dans 34 pays) ; le contrôle se fait à la plaque via le FVA.`}}]}],u={slug:`assurance-temporaire-convoyage-professionnel`,seo:{title:`Convoyage professionnel : quelle assurance pour le véhicule que vous déplacez ?`,description:`Mandataires, négociants, transporteurs : assurez chaque véhicule convoyé (roulant) avec une assurance temporaire de 1 à 90 jours, sans contrat annuel inutile. Attestation en 5 minutes.`,canonical:`https://assutempo.fr/articles/assurance-temporaire-convoyage-professionnel`,jsonLd:l},category:`Pro & convoyage`,readTime:`4 min`,updatedDate:`3 juin 2026`,author:`Evidence Assurances`,headline:`Convoyage professionnel : quelle assurance ?`,immediateAnswer:`Pour convoyer un véhicule par la route, sur ses propres roues, il doit avoir une assurance responsabilité civile en cours, même pour un seul trajet. L'assurance temporaire couvre chaque véhicule convoyé pour la durée exacte du déplacement, sans souscrire de contrat annuel pour un véhicule qui ne fait que passer.`,sections:[{type:`alert`,heading:`L'essentiel`,items:[`Un véhicule convoyé sur ses roues doit avoir une RC circulation valide, même pour un trajet unique.`,`L'assurance temporaire couvre ce véhicule pour la durée du convoyage (1 à 90 jours), sans engagement.`,`Souple pour les pros qui déplacent des véhicules de passage : mandataires, négociants, garages, transporteurs, import-export.`,`À distinguer de la RC Pro du convoyeur (sa responsabilité professionnelle), qui est un contrat séparé.`]},{type:`stepflow`,ariaLabel:`Comment assurer un convoyage professionnel en 4 étapes : durée, véhicule, paiement, attestation`,steps:[{icon:i,label:`Choisissez la durée du convoyage (1 à 90 j)`},{icon:o,label:`Renseignez le véhicule à convoyer`},{icon:n,label:`Payez en ligne`},{icon:r,label:`Recevez l'attestation (5 min)`}]},{type:`text`,heading:`Faut-il assurer un véhicule pour le convoyer ?`,paragraphs:[`Oui, dès qu'il roule sur ses propres roues sur la voie publique. La responsabilité civile (l'assurance au tiers) est obligatoire, y compris pour un convoyage d'un point A à un point B. Convoyer un véhicule sans assurance expose aux mêmes sanctions qu'un défaut d'assurance classique.`],relatedLink:{text:`Contrôlé sans assurance : risques, amende et que faire`,href:`/articles/controle-sans-assurance-risques-amende`}},{type:`text`,heading:`Quelle assurance pour le véhicule convoyé ?`,paragraphs:[`L'assurance temporaire au véhicule. Elle couvre la RC circulation du véhicule que vous déplacez, pour la durée exacte du trajet (1 à 90 jours), sans engager de contrat annuel pour un véhicule de passage. C'est la solution souple quand vous convoyez ponctuellement un véhicule qui n'est pas, ou pas encore, sur votre flotte.`],relatedLink:{text:`Assurer un véhicule acheté chez un particulier`,href:`/articles/assurer-vehicule-achete-chez-particulier`}},{type:`text`,heading:`Et la RC Pro du convoyeur ?`,paragraphs:[`À ne pas confondre. La RC Pro (responsabilité civile professionnelle) couvre VOTRE activité de convoyeur, les dommages causés aux tiers dans le cadre de vos missions, souvent exigée par les donneurs d'ordre. C'est un contrat distinct de l'assurance du véhicule convoyé. L'assurance temporaire assure le véhicule pour rouler ; les deux sont complémentaires.`]},{type:`text`,heading:`Pour quels professionnels ?`,paragraphs:[`Mandataires auto, négociants, garages, concessionnaires, transporteurs, professionnels de l'import-export. Dès que vous prenez le volant d'un véhicule à déplacer qui n'est pas déjà couvert, l'assurance temporaire répond au besoin, voiture, utilitaire comme poids lourd, avec le permis adapté.`],relatedLink:{text:`Devenir partenaire AssuTempo`,href:`/qui-sommes-nous`}},{type:`checklist`,heading:`Quels documents pour souscrire ?`,items:[`La carte grise du véhicule (ou la preuve de propriété / le numéro de châssis)`,`Le permis adapté du convoyeur`,`Un moyen de paiement (carte bancaire)`]},{type:`text`,heading:`Quels documents reçoit-on avec l'assurance ?`,paragraphs:[`Depuis avril 2024, la carte verte n'existe plus. En France, la preuve d'assurance se fait à la plaque, via le Fichier des Véhicules Assurés (FVA). Le contrat comprend le Mémo Véhicule Assuré et la carte internationale d'assurance automobile, valable dans les 34 pays, utile pour un convoyage transfrontalier.`],relatedLink:{text:`Véhicule ou permis étranger : assurance temporaire en France`,href:`/articles/assurance-temporaire-vehicule-etranger-france`}}],faqItems:[{q:`Un véhicule convoyé sur la route doit-il être assuré ?`,a:`Oui, la RC est obligatoire dès qu'il roule sur ses propres roues, même pour un trajet unique.`},{q:`Faut-il un contrat annuel pour convoyer un véhicule ?`,a:`Non. L'assurance temporaire (1 à 90 jours) couvre exactement la durée du convoyage, sans engagement.`},{q:`Assurance temporaire ou RC Pro convoyeur ?`,a:`Les deux sont distinctes et complémentaires : l'assurance temporaire couvre le véhicule pour rouler, la RC Pro couvre votre responsabilité professionnelle de convoyeur.`},{q:`Peut-on assurer un véhicule pas encore à mon nom ?`,a:`Oui, à partir de la carte grise, de la preuve de propriété ou du numéro de châssis.`},{q:`Le convoyage à l'étranger est-il couvert ?`,a:`Oui, la carte internationale d'assurance couvre les 34 pays.`},{q:`Reçoit-on une carte verte ?`,a:`Non, elle a été supprimée. Mémo Véhicule Assuré + carte internationale (34 pays) ; contrôle à la plaque via le FVA.`}]}}));function f(){return(0,p.jsx)(c,{data:u})}var p;e((()=>{s(),d(),p=t()}))();export{f as default};